<script setup lang="ts">
import {visualVariables} from '@/domain/visual';
import {computed,ref,watch,onUnmounted} from 'vue';import AppEmptyState from './AppEmptyState.vue';import type {Theme,Vod} from '@/domain/types';import {assetUrl} from '@/services/api';
const props=defineProps<{theme:Theme;items:Vod[];editing?:boolean;nativeMobile?:boolean;designPreview?:boolean;imageResolver?:(value:string)=>string}>();const emit=defineEmits<{open:[vod:Vod];page:[page:string];id:[id:string];select:[id:string]}>();const active=ref(0);const rows=computed(()=>{const actual=props.theme.carousel.slides.length?props.theme.carousel.slides.map(s=>({id:s.id,title:s.title,image:s.image,video:s.video,vodId:s.vodId,vod:props.items.find(v=>v.id===s.vodId),page:s.page})):props.items.slice(0,5).map(v=>({id:v.id,title:v.title,image:v.poster,video:'',vodId:v.id,vod:v,page:'home'}));return actual.length||!props.designPreview?actual:[1,2,3].map(n=>({id:'design-'+n,title:['光影之间','发现好故事','让精彩发生'][n-1],image:'',video:'',vodId:'',vod:undefined,page:'home'}));});
let timer:ReturnType<typeof setInterval>|undefined;let touchX=0;
function step(by:number){if(rows.value.length)active.value=(active.value+by+rows.value.length)%rows.value.length;}
watch(()=>[props.theme.carousel.effect,props.theme.carousel.autoplay,props.theme.carousel.interval,props.editing,rows.value.length],()=>{if(timer)clearInterval(timer);active.value=Math.min(active.value,Math.max(0,rows.value.length-1));if(props.theme.carousel.effect==='fade'&&props.theme.carousel.autoplay&&!props.editing&&rows.value.length>1)timer=setInterval(()=>step(1),props.theme.carousel.interval*1000);},{immediate:true});
onUnmounted(()=>{if(timer)clearInterval(timer);});
function touchStart(e:any){touchX=e.changedTouches?.[0]?.clientX||0;}
function touchEnd(e:any){const delta=(e.changedTouches?.[0]?.clientX||0)-touchX;if(Math.abs(delta)>35)step(delta>0?-1:1);}
function open(s:typeof rows.value[number]){if(s.id.startsWith('design-')){emit('select','hero');return;}if(props.editing)emit('select','hero');else if(s.vod)emit('open',s.vod);else if(s.vodId)emit('id',s.vodId);else emit('page',s.page);}
</script>
<template><view class="carousel" :class="'carousel-'+theme.carousel.style" :style="{...visualVariables(theme),'--height':theme.carousel.height+'px','--radius':theme.carousel.radius+'px','--margin':theme.carousel.margin+'px'}"><swiper v-if="theme.carousel.effect!=='fade'" :style="{height:theme.carousel.height+'px'}" :autoplay="theme.carousel.autoplay&&!editing" :interval="theme.carousel.interval*1000" :current="active" :circular="rows.length>1" :indicator-dots="theme.carousel.indicator==='dots'&&!nativeMobile" :indicator-active-color="theme.colors.accent" :previous-margin="theme.carousel.style==='peek'?(theme.visual?.carousel.peek??24)+'px':'0px'" :next-margin="theme.carousel.style==='peek'?(theme.visual?.carousel.peek??24)+'px':'0px'" :duration="Number(theme.visual?.carousel.duration??550)" @change="active=$event.detail.current"><swiper-item v-for="(s,i) in rows" :key="s.id"><view class="slide"  @click="open(s)"><video v-if="theme.carousel.style==='video'&&s.video&&active===i" :src="assetUrl(s.video)" :muted="theme.carousel.muted" :autoplay="!editing" loop :controls="false"/><image v-else-if="s.image" :src="imageResolver?imageResolver(s.image):assetUrl(s.image)" :mode="theme.carousel.fit==='contain'?'aspectFit':'aspectFill'"/><view v-if="!s.image&&!s.video" class="design-art" :class="'art-'+i"><view class="orb"/><view class="art-grid"/><text>THEME / 0{{i+1}}</text><text class="reference-label">离线排版示意</text></view><view class="hero-copy" :class="'title-'+theme.carousel.titlePosition" v-if="theme.carousel.titlePosition!=='hidden'"><text class="hero-label">{{theme.brand.tagline}}</text><text class="hero-title">{{s.title}}</text><text class="hero-play">{{s.id.startsWith('design-')?'设计示意 · 内容由运营配置':'立即观看 ›'}}</text></view></view></swiper-item></swiper><view v-else class="fade-stage" :style="{height:theme.carousel.height+'px'}" @touchstart="touchStart" @touchend="touchEnd"><template v-for="(s,i) in rows" :key="s.id"><view class="slide fade-item" :class="{'is-active':active===i}" :style="{opacity:active===i?1:0,pointerEvents:active===i?'auto':'none'}"  @click="open(s)"><video v-if="theme.carousel.style==='video'&&s.video&&active===i" :src="assetUrl(s.video)" :muted="theme.carousel.muted" :autoplay="!editing" loop :controls="false"/><image v-else-if="s.image" :src="imageResolver?imageResolver(s.image):assetUrl(s.image)" :mode="theme.carousel.fit==='contain'?'aspectFit':'aspectFill'"/><view v-if="!s.image&&!s.video" class="design-art" :class="'art-'+i"><view class="orb"/><view class="art-grid"/><text>THEME / 0{{i+1}}</text><text class="reference-label">离线排版示意</text></view><view class="hero-copy" :class="'title-'+theme.carousel.titlePosition" v-if="theme.carousel.titlePosition!=='hidden'"><text class="hero-label">{{theme.brand.tagline}}</text><text class="hero-title">{{s.title}}</text><text class="hero-play">{{s.id.startsWith('design-')?'设计示意 · 内容由运营配置':'立即观看 ›'}}</text></view></view></template><view v-if="rows.length>1&&!nativeMobile" class="fade-controls"><text tabindex="0" @click.stop="step(-1)" @keydown.enter="step(-1)">‹</text><view v-if="theme.carousel.indicator==='dots'" class="fade-dots"><text v-for="(s,i) in rows" :key="s.id" :style="{background:active===i?theme.colors.accent:'#ffffff70'}" @click.stop="active=i"> </text></view><text tabindex="0" @click.stop="step(1)" @keydown.enter="step(1)">›</text></view></view><view v-if="nativeMobile&&theme.carousel.indicator==='dots'&&rows.length>1" class="native-dots"><view v-for="(row,i) in rows" :key="row.id" :class="{active:active===i}" role="button" :aria-label="'轮播第'+(i+1)+'张'" @click.stop="active=i"/></view><view v-if="theme.carousel.indicator==='numbers'&&rows.length" class="numbers">{{active+1}} / {{rows.length}}</view><view v-if="!rows.length" class="placeholder" @click="editing&&emit('select','hero')"><AppEmptyState class="carousel-empty" title="精彩即将呈现" :description="editing?'添加轮播图片，打造你的首页':'暂时没有推荐内容'" icon="play"/></view></view></template>
<style scoped>.carousel{margin:var(--margin);position:relative}.slide{height:100%;position:relative;overflow:hidden;border-radius:var(--radius);background:var(--surface)}.slide image,.slide video{width:100%;height:100%}.hero-copy{position:absolute;bottom:0;left:0;right:0;padding:40px 18px 24px;background:linear-gradient(transparent,#000b);color:#fff;display:flex;flex-direction:column;gap:6px}.hero-label{font-size:10px;opacity:.7}.hero-title{font-size:24px;font-weight:700}.hero-play{font-size:11px;color:#d9e9f3}.carousel-inset{padding:8px 14px}.carousel-peek .slide{margin:0 5px}.carousel-poster .slide{margin:0 auto;width:65%}.carousel-poster image{object-fit:contain}.carousel-split .slide{display:flex}.carousel-split .slide image{width:58%;order:1}.carousel-split .hero-copy{position:static;width:42%;justify-content:center;background:var(--surface);padding:15px}.carousel-split .hero-title{font-size:20px}.title-side{left:0;width:50%;bottom:20%;right:auto;background:linear-gradient(90deg,#0009,transparent)}.numbers{position:absolute;bottom:10px;right:15px;color:#fff;font-size:10px;background:#0007;padding:3px 7px;border-radius:5px}.placeholder{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:12px;color:var(--muted);background:var(--surface)}.fade-stage{position:relative;overflow:hidden;border-radius:var(--radius)}.fade-item{position:absolute;inset:0;transition:opacity .55s ease}.fade-controls{position:absolute;left:10px;right:10px;bottom:10px;display:flex;align-items:center;justify-content:space-between;color:#fff;pointer-events:none}.fade-controls>text{pointer-events:auto;padding:0 12px;font-size:25px;background:#0006;border-radius:20px}.fade-dots{display:flex;gap:6px;pointer-events:auto}.fade-dots text{width:6px;height:6px;border-radius:50%}.carousel-poster .fade-item{left:17.5%;right:17.5%;width:auto}.native-dots{position:absolute;right:10px;bottom:14px;display:flex;gap:3px;align-items:center}.native-dots>view{width:3px;height:3px;border-radius:2px;background:#ffffff66;cursor:pointer}.native-dots>view.active{width:12px;background:#fff}</style>
<style scoped>
.carousel .hero-title{font-size:var(--design-carousel-titleSize,24px)}
.carousel:not(.carousel-split) .hero-copy:not(.title-side){background:linear-gradient(transparent,rgba(0,0,0,calc(var(--design-carousel-overlay,65) / 100)))}
.carousel-split .hero-copy{background:var(--surface)}
.carousel:not(.carousel-split) .hero-copy.title-side{background:linear-gradient(90deg,rgba(0,0,0,calc(var(--design-carousel-overlay,65) / 100)),transparent)}
.carousel .fade-item{transition-duration:var(--design-carousel-duration,550ms)}
.design-art{position:absolute;inset:0;overflow:hidden;background:linear-gradient(145deg,#103c49,#1b203e 60%,#121728);color:#ffffff85}.design-art.art-1{background:linear-gradient(145deg,#3e304c,#203046 70%,#121725)}.design-art.art-2{background:linear-gradient(145deg,#4a4431,#213f41 65%,#101c29)}.orb{position:absolute;width:180px;height:180px;border-radius:50%;border:1px solid #ffffff30;right:20px;top:20px;box-shadow:0 0 0 25px #ffffff04,0 0 0 50px #ffffff04}.art-grid{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent,transparent 48px,#ffffff05 49px,transparent 50px)}.design-art>text{position:absolute;top:20px;left:20px;font-size:10px;letter-spacing:2px}.design-art .reference-label{top:20px;left:auto;right:20px;letter-spacing:.5px;font-size:9px;border:1px solid #ffffff25;border-radius:20px;padding:4px 8px}
@media(prefers-reduced-motion:reduce){.carousel .fade-item{transition:none}}
</style>
